#include <QApplication>
#include <QMatrix>
#include <QPixmap>
#include <QImage>
#include <QWidget>
#include <QLabel>
#include <QZoomWidget>

class MatrixBitmap : public QObject
{
    Q_OBJECT
public:
    MatrixBitmap(const QMatrix& matrix) : m_matrix(matrix) {}

    QPixmap render() const {
        QImage image(m_matrix.columns(), m_matrix.rows(), QImage::Format_RGB32);
        for (int i = 0; i < m_matrix.rows(); ++i) {
            for (int j = 0; j < m_matrix.columns(); ++j) {
                image.setPixel(j, i, qRgb(m_matrix(i, j), m_matrix(i, j), m_matrix(i, j)));
            }
        }
        return QPixmap::fromImage(image);
    }

private:
    const QMatrix& m_matrix;
};

class ZoomableBitmapWidget : public QWidget
{
    Q_OBJECT
public:
    ZoomableBitmapWidget(MatrixBitmap* matrixBitmap) : m_matrixBitmap(matrixBitmap) {}

protected:
    void paintEvent(QPaintEvent*) override {
        QPainter painter(this);
        painter.drawPixmap(0, 0, *m_matrixBitmap->render());
    }
};

