To create professional access permissions guards based on user roles with a list of permissions, you can create a custom middleware function that checks the user's role and grants or denies access based on the permissions associated with that role. Here's an example:

```javascript
import { Injectable, CanActivate, ExecutionContext } from '@nestjs/common';

@Injectable()
export class PermissionsGuard implements CanActivate {
  async canActivate(context: ExecutionContext): Promise<boolean> {
    const req = context.switchToHttp().getRequest();
    const user = req.user;
    const permissionName = req.params.permissionName;

    if (!user || !user.roles) {
      return false;
    }

    const hasPermission = user.roles.some((role) => role.permissions.includes(permissionName));

    return hasPermission;
  }
}
```

